wacorpApp.directive('downloadFile', function ($compile, $window, wacorpService, $rootScope) {
    return {
        restrict: 'A',
        replace: false,
        //template: '<a href="" class="btn btn-primary" ng-click="downloadPdf()">Download</a>',
        scope: {
            params: "=",
            filename: "="
        },
        link: function (scope, element, attr) {
            var isClickable = angular.isDefined(attr.ngClick);
            if (!isClickable) {
                attr.$set('ngClick', 'downloadPdf()');
                $compile(element)(scope);
            }

            // When the download starts, disable the link
            //scope.$on('download-start', function () {});

            // When the download finishes, attach the data to the link. Enable the link and change its appearance.
            //scope.$on('downloaded', function (event, data) {

            //});
        },
        controller: ['$scope', '$attrs', '$http', '$timeout', function ($scope, $attrs, $http, $timeout) {

            // Actually performs the download once a Turnstile token is available.
            function doDownload(token) {
                var params = $scope.params;
                var url = baseUrl + $attrs.url;

                if ($rootScope.repository.loggedUser != undefined)
                    $http.defaults.headers.common['Authorization'] = 'Bearer ' + $rootScope.repository.loggedUser.t;
                $http({
                    method: "POST",
                    url: url,
                    data: params,
                    headers: {
                        accept: 'application/octet-stream', //or whatever you need
                        'X-reCAPTCHA': token
                    },
                    responseType: 'arraybuffer',
                    cache: false,
                    transformResponse: function (data, headers) {
                        headers = headers();
                        if (headers['content-type'] == undefined || headers['content-type'] != 'application/octet-stream') {
                            var message = "File Not Found";
                            try {
                                var text = "";
                                if (typeof data === 'string') {
                                    text = data;
                                } else if (data) {
                                    text = new TextDecoder('utf-8').decode(new Uint8Array(data));
                                }
                                text = (text || '').trim();
                                if (text) {
                                    // server may return a JSON-encoded string (wrapped in quotes)
                                    try { text = JSON.parse(text); } catch (e) { /* not JSON, keep raw text */ }
                                    if (text) { message = text; }
                                }
                            } catch (e) { /* fall back to default message */ }
                            wacorpService.alertDialog(message);
                        }
                        else {
                            var file = new Blob([data], {
                                type: 'application/octet-stream' //or whatever you need, should match the 'accept headers' above
                            });
                            saveAs(file, $scope.params.FileName || $scope.filename);
                        }
                    },
                })
                    .then(function (result) {
                        // token is single-use: reset the widget so a fresh token is generated
                        if (window.turnstile && window.turnstile.reset) window.turnstile.reset();
                        $rootScope.reCaptcha = null;
                    }, function (error) {
                        if (window.turnstile && window.turnstile.reset) window.turnstile.reset();
                        $rootScope.reCaptcha = null;
                    });
            }

            $scope.downloadPdf = function () {
                // Token already present (also covers the "local" seed when Turnstile is disabled).
                if ($rootScope.reCaptcha) {
                    doDownload($rootScope.reCaptcha);
                    return;
                }

                // Wait for the cf-turnstile widget on this page to produce a token, then fire.
                var unwatch = $scope.$watch(function () {
                    return $rootScope.reCaptcha;
                }, function (token) {
                    if (token) {
                        $timeout.cancel(giveUp);
                        unwatch();
                        doDownload(token);
                    }
                });

                // Safety net: never hang forever if no widget is present / verification fails.
                var giveUp = $timeout(function () {
                    unwatch();
                    if (!$rootScope.reCaptcha)
                        wacorpService.alertDialog("Verification could not be completed. Please refresh the page and try again.");
                }, 15000);
            };
        }]
    }
});

